#!/usr/bin/env python3
"""Read-only world checks, proxy calibration, regression and cost accounting."""
from __future__ import annotations
import argparse
import base64
import hashlib
import json
import struct
import subprocess
from pathlib import Path

from vanilla_search.extract import extract_region
from vanilla_search.evaluate import evaluate_orientation
from vanilla_search.fit import enrich
from vanilla_search.staged import save, ROOT

def report(out,summary,audit):
    a=summary['screen'];cost=audit['cost'];generated=summary['generated'];n=len(generated)
    lines=['# Completed staged vanilla Default search','', '> Prototype/test finalist set. No final map selection, terrain correction or competitive systems are implemented.', '', '## Funnel and measured cost','', '| Stage | Input → output | Measured time | Throughput |','|---|---:|---:|---:|',f'| A: native coarse biome screen | {a["windows"]:,} → {a["stage_a_survivors"]:,} windows | {a["stage_a_seconds"]:.2f} s | {cost["stage_a_windows_per_second"]:,.1f} windows/s |',f'| B: native structural ranking | {a["stage_a_survivors"]:,} → {a["stage_b_survivors"]:,} viable proxies → {n} diverse generation selections | {a["stage_b_seconds"]:.2f} s | {cost["stage_b_windows_per_second"]:,.1f} windows/s |',f'| C: official 1.21.11 acquisition | {n} → {n} complete windows | {cost["full_acquisition_seconds"]:.2f} s | {cost["full_generation_regions_per_second"]:.4f} windows/s |',f'| C: final ground extraction | {n} complete windows | {cost["stage_c_extraction_seconds"]:.2f} s | {n/cost["stage_c_extraction_seconds"]:.3f} windows/s |',f'| C: final actual-terrain analysis | {n} → {summary["finalist_count"]} finalists | {cost["stage_c_analysis_seconds"]:.2f} s | {n/cost["stage_c_analysis_seconds"]:.3f} windows/s |',f'| D: final analytical fit | {summary["finalist_count"]} finalists | {cost["stage_d_fit_seconds"]:.2f} s | {summary["finalist_count"]/max(.001,cost["stage_d_fit_seconds"]):.3f} finalists/s |','',f'A searched {a["seeds"]:,} seeds at five centers each: (0,0), (±2048,0), (0,±2048). Windows are 864×1056 raw blocks. A rejected {a["windows"]-a["stage_a_survivors"]:,} ({1-a["stage_a_survivors"]/a["windows"]:.2%}); reasons: `{a["stage_a_rejections"]}`. B rejected {a["stage_a_survivors"]-a["stage_b_survivors"]:,} ({1-a["stage_b_survivors"]/a["stage_a_survivors"]:.2%}); {a["stage_b_survivors"]-n:,} viable proxies were not selected for the limited generation budget. They are not claimed to be terrain failures.', '',f'Official generation: **{n} worlds, {cost["evaluated_full_chunks"]:,} requested full chunks**, {cost["full_generation_cpu_seconds"]:.1f} CPU-seconds; serial servers with 3 GB maximum Java heap each. Retained worlds occupy {cost["retained_world_bytes"]/1024**2:.1f} MiB. Saved chunk-slot counts, including spawn/halo chunks, are recorded per world in `validation_and_cost.json`; the requested chunk count does not hide that extra generation. No finalist was regenerated. JAR SHA-1: `64bb6d763bed0a9f1d632ec347938594144943ed`.', '', 'Times above are measured stage service times, not the elapsed interactive development session. Native compile/setup, presentation rendering, hashing, regression re-extraction and operator review are outside those stage rates. Preliminary extraction/analysis before the snow-on-canopy correction is preserved separately in `pre_ground_scan_analysis_summary.json`; these validation passes incurred parsing work but no extra Minecraft generation. The separate 5,000-window pilot took 5.27 s and is not included in the 100,000-window production counts.', '', '## Method and metric decisions','', 'A uses 63 stored-quart biome samples at Y96 per window, spacing 128 blocks, to reject absent ocean/highland opportunity and ocean domination. B uses 891 samples at 32-block spacing and four W/E axis assignments. These are biome proxies only. No terrain simulation, structure search, resource inventory or pathfinding runs in the bulk funnel. A soft composition bottleneck rank rewards simultaneous coast, highland, cold, open ground, forest and homeland opportunity; farthest-first composition diversity then operates within the leading 1% (at least 80) of ranked B survivors, with distinct seeds. These prototype ranking scales are not game-design thresholds.', '', 'C uses the pinned official Java 1.21.11 dedicated server and existing full-chunk extractor. Real surface water, relief, biome regions, dry connectivity, open substrate, cold highland evidence and homeland footprints determine fit. A 64-block capped downward scan distinguishes snowy tree canopies from ground. Actual open-ground credit requires non-canopied soil/sand/gravel and modest sampled roughness. D alone runs six analytical paths, with uncapped elevation cost to discourage cliff shortcuts, and adds homeland footprints, center, provisional POI nodes, regional adjacency, crossing/steep-step warnings and shared-corridor counts.', '', 'Retained: official acquisition, Anvil/NBT reader, eight-way orientation utility, real surface/biome/fluid/structure evidence, compact grids and clean-world inspection setup. Demoted: legacy composite score and warning contract; relative highland column counts; biome-only openness; automatic path connectivity as proof of walkability; exact villages/resources/ecology. Added: cheap A/B, composition diversity, real canopy/open substrate, connected regional relationships, explicit bounds/axes, analytical POIs and footprint/crossing diagnostics. Existing POC code/results remain available.', '', 'C hard filters are only absent eastern ocean, reversed ocean axis, absent western highland, catastrophic dry fragmentation, or lack of plausible development sites. No exact animal/crop/ore/village count is used. Dimensions and 72×72 homeland footprints are prototype tests, not settled scale decisions. Rotations can exchange logical width/height; no terrain is rotated. N/S reversal and reflection are equivalent duplicate interpretations before teams are assigned.', '', '## Finalists','', '| Seed | Raw center | Inclusive X / Z bounds | Logical N / E | Open ground / west highland | Review |','|---|---|---|---|---|---|']
    svg=['<svg xmlns="http://www.w3.org/2000/svg" width="920" height="1960"><rect width="100%" height="100%" fill="#14211d"/><g font-family="sans-serif" fill="white"><text x="24" y="30" font-size="22">Eight real vanilla regions · actual ground / canopy</text>']
    for index,seed in enumerate(summary['finalist_seeds']):
        c=json.loads((out/'finalists'/str(seed)/'candidate.json').read_text());m=c['stage_c'];b=c['region']['block_bounds'];g=c['greybox'];axes=g['logical_axes_in_minecraft']
        lines.append(f'| {seed} | {c["region"]["source_center"]} | {b[0]}…{b[1]} / {b[2]}…{b[3]} | {axes["North"]} / {axes["East"]} | {m["genuine_open_ground_fraction"]:.1%} / {m["western_highland_fraction"]:.1%} | [fit and inspection](finalists/{seed}/REVIEW.md) |')
        x=20+(index%2)*450;y=50+(index//2)*475
        encoded=base64.b64encode((out/'finalists'/str(seed)/'05_actual_ground_canopy.png').read_bytes()).decode()
        svg.extend([f'<text x="{x}" y="{y+20}" font-size="18">{seed} · N {axes["North"]} / E {axes["East"]}</text>',f'<image x="{x}" y="{y+32}" width="420" height="390" preserveAspectRatio="xMidYMid meet" href="data:image/png;base64,{encoded}"/>',f'<text x="{x}" y="{y+443}" font-size="13">Open {m["genuine_open_ground_fraction"]:.0%} · canopy {m["actual_canopy_fraction"]:.0%} · ocean E {m["eastern_ocean_fraction"]:.0%}</text>'])
    svg.append('</g></svg>');(out/'COMPARISON.svg').write_text('\n'.join(svg))
    lines+=['','[Visual comparison](COMPARISON.svg). Pale green = sampled open ground, dark green = canopy, grey = exposed rock, white = snow/ice, blue = actual water. The per-finalist biome and height maps provide complementary evidence. Each `REVIEW.md` records landscape regions/relationships, center, principal weakness, correction burden, homeland and Route fit, POIs and world path.', '', '## Regression references and evidence boundaries','', '| Region | Actual open ground | Actual canopy | Eastern ocean | Western cold highland samples |','|---|---:|---:|---:|---:|']
    for seed,record in audit['reference_comparison'].items():
        m=record['stage_c'];lines.append(f'| {seed} | {m["genuine_open_ground_fraction"]:.1%} | {m["actual_canopy_fraction"]:.1%} | {m["eastern_ocean_fraction"]:.1%} | {m["western_cold_highland_samples"]} |')
    lines+=['','The references were re-extracted from their existing official worlds in their historical chosen orientations, not regenerated or silently reoriented. The specification supplies the qualitative interpretation: 002 has useful directionality but weaker differentiation; 003 has rich formations/open country but weaker W/E arrangement. Numeric canopy is sampled cover, not an attempt to override those interior visual judgments. New finalists should be compared for the combination of traits rather than one scalar score.', '', f'Cubiomes revision `e61f90580cbdd883214a8054670dacae655e59c0` ([upstream](https://github.com/Cubitect/cubiomes)) advertises MC_1_21 Winter Drop, not explicit 1.21.11 fidelity. Same-coordinate quart-palette spot checks matched {sum(v["exact_stored_quart_biome_matches"] for v in audit["calibration"].values())}/{sum(v["samples"] for v in audit["calibration"].values())} samples across references and finalists. This is empirical compatibility evidence, not a complete generator equivalence proof. Initial block-Voronoi comparisons were replaced with the appropriate stored-quart comparison.', '', 'Evidence layers: A/B are cheap proxies; C measurements and raster images come from actual vanilla chunks; D boxes, corridors, region labels and POI nodes are analytical hypotheses; interior legibility and final playability remain manual. No Minecraft first-person playtest has been performed in this task. See `VISUAL_REVIEW.md` for explicit overhead-image judgment.', '', '## Limitations and handoff','', 'Eight-block sampling misses narrow barriers, caves, small passes and individual obstructions. The ground scan can stop at structure roofs or unusual unclassified blocks and has a 64-block cap. It is not a complete block collision model. The region graph describes surface adjacency, not verified traversal. A* has finite cost everywhere; six paths do not prove six independent or balanced Routes. Shared paths and rough/wet segments are exposed for review. Homeland flatness is a local opportunity proxy, not resource fairness or a guarantee of construction-ready 72×72 floors.', '', 'Manual/later: regional interiors, sightlines, landmark quality, internal mountain passes/valleys, cave/ravine entrances, alternative crossings, actual bridge/stair/clearing burden, expedition timing, homeland resources/defenses, competitive equivalence, authored village network and ecological/resource guarantees. No macro repair is proposed. Reject a finalist if manual inspection would require mountain/coast/river/biome replacement.', '', 'Clean worlds: `artifacts/worldgen/staged_default_2026-09-09/worlds/` at repository root. They are local, gitignored bulk artifacts, not included in the Git push. Each folder opens in Java 1.21.11 and includes `INSPECTION.json`, `GREYBOX.json` and chunk hashes. Committed artifacts include the comparison, detailed reviews, labeled SVGs, actual rasters, candidate metadata, all B survivors, queue, counts, acquisition timings and validation results.', '', 'Recommended next step: manually fly the strongest open-interior candidates and the contrasting alpine/coastal options using the labeled bounds; inspect both homeland footprints, western approaches and flagged crossings. Choose one substrate only after this review, then plan modest authored infrastructure and resource/ecology work. Do not start macro terrain repair.', '']
    extra=['## Selective refinement and review decisions','']
    if (out/'temperate_refinement.json').exists():
        ref=json.loads((out/'temperate_refinement.json').read_text())
        extra += [f'Overhead review of the initial eight revealed too much broadly snowy coast. A cheap refinement resampled the leading {ref["input_windows"]:,} existing B survivors in {ref["seconds"]:.2f} s ({ref["windows_per_second"]:.1f} windows/s), distinguishing temperate open interior, snowy plains and western peak/slope biomes. It selected exactly three additional official worlds. These are repeated cheap evaluations of existing windows, not an expanded blind generation batch.', '']
    extra += [f'Final review retained {summary["finalist_count"]}/{n} generated candidates. The following are manual/analytical selection exclusions, not hidden full-generation failures:','']
    for seed,reason in summary.get('review_exclusions',{}).items(): extra.append(f'- {seed}: {reason}')
    extra += ['',f'All {n} generated worlds remain available: {cost.get("all_generated_world_bytes",0)/1024**2:.1f} MiB and {cost.get("all_saved_overworld_chunk_slots",0):,} saved Overworld chunk slots including spawn/halo/protochunks. Excluded review packages are under `review_excluded/`; their worlds remain clean. Finalist-only disk size is reported separately above.','']
    position=lines.index('## Method and metric decisions');lines[position:position]=extra
    (out/'REPORT.md').write_text('\n'.join(lines))

def main():
    p=argparse.ArgumentParser();p.add_argument('--out',type=Path,default=ROOT/'implementation/worldgen/results/staged_default_2026-09-09');p.add_argument('--artifacts',type=Path,default=ROOT/'artifacts/worldgen/staged_default_2026-09-09');args=p.parse_args()
    out=args.out;build=args.artifacts/'build';summary=json.loads((out/'search_summary.json').read_text())
    audit={'reference_comparison':{},'finalists':{},'worlds':{},'calibration':{}}
    for seed in [920270002,920270003]+[r['seed'] for r in summary['generated']]:
        reference=seed in (920270002,920270003)
        category='finalists' if seed in summary['finalist_seeds'] else 'review_excluded'
        path=(ROOT/'implementation/worldgen/results/vanilla_default_poc_2026-09-09/shortlist'/str(seed)/'candidate.json') if reference else out/category/str(seed)/'candidate.json'
        c=json.loads(path.read_text());world=Path(c['local_world_directory']);b=c['region']['chunk_bounds'];o=c['orientation']
        if reference: checkpoint=build/f'reference_{seed}.extracted.json'
        else: checkpoint=build/f"{seed}_{c['region']['source_center'][0]}_{c['region']['source_center'][1]}.extracted.json"
        e=json.loads(checkpoint.read_text()) if checkpoint.exists() else None
        if not e or not e.get('ground_scan'): e=extract_region(world,b,ground_scan=True);save(checkpoint,e)
        if reference:
            a=evaluate_orientation(e,o['rotation_degrees_clockwise'],o['east_west_reflected'],fit_routes=False);enrich(a);audit['reference_comparison'][str(seed)]={'stage_c':a['stage_c'],'orientation':o,'source':'new analysis of existing official chunks; no regeneration'}
        cells=sum(e['rows'],[])[::31]
        query=''.join(f"{seed} {a['x']} {max(a['terrain_y'],63)} {a['z']}\n" for a in cells)
        names=subprocess.run([str(build/'coarse'),'--probe'],input=query,text=True,capture_output=True,check=True).stdout.splitlines()
        assert len(names)==len(cells)
        matches=sum(name==a['biome'].removeprefix('minecraft:') for name,a in zip(names,cells))
        audit['calibration'][str(seed)]={'samples':len(cells),'exact_stored_quart_biome_matches':matches,'match_fraction':round(matches/len(cells),5),'method':'same quart coordinates and surface sampling Y; library MC_1_21 versus official 1.21.11'}
        if not reference:
            manifest=json.loads((world/'INSPECTION.json').read_text());hashes=manifest['chunk_file_sha256']
            for name,digest in hashes.items():
                assert hashlib.sha256((world/name).read_bytes()).hexdigest()==digest,(seed,name)
            slots=0;size=0;files=0
            for f in world.rglob('*'):
                if f.is_file(): size+=f.stat().st_size;files+=1
            for f in (world/'region').glob('*.mca'):
                with f.open('rb') as source: header=source.read(4096)
                slots+=sum(bool(v) for v in struct.unpack('>1024I',header))
            bounds=c['region']['block_bounds']
            for home in c['greybox']['homelands'].values():
                bb=home['raw_footprint_bounds'];assert bounds[0]<=bb[0]<=bb[1]<=bounds[1] and bounds[2]<=bb[2]<=bb[3]<=bounds[3]
            assert len(c['routes']['branches'])==6
            for branch in c['routes']['branches']:
                assert branch['raw_world_path']
                assert all(bounds[0]<=x<=bounds[1] and bounds[2]<=z<=bounds[3] for x,z in branch['raw_world_path'])
            audit['worlds'][str(seed)]={'verified_chunk_file_hashes':len(hashes),'evaluated_full_chunks':e['full_chunks'],'saved_overworld_chunk_slots_including_halo_and_spawn':slots,'world_bytes':size,'world_files':files,'bounds_routes_homeland_footprints_valid':True,'finalist':seed in summary['finalist_seeds']}
            if seed in summary['finalist_seeds']: audit['finalists'][str(seed)]=audit['worlds'][str(seed)]
    generated=summary['generated'];a=summary['screen'];t=sum(c['timing']['total_acquisition_seconds'] for c in generated)
    audit['cost']={'stage_a_windows_per_second':a['windows']/a['stage_a_seconds'],'stage_b_windows_per_second':a['stage_a_survivors']/a['stage_b_seconds'],'full_acquisition_seconds':t,'full_generation_regions_per_second':len(generated)/t,'full_generation_cpu_seconds':sum(c['timing'].get('server_cpu_seconds',0) for c in generated),'evaluated_full_chunks':len(generated)*54*66,'stage_c_extraction_seconds':sum(c['timing']['extraction_seconds'] for c in generated),'stage_c_analysis_seconds':sum(c['timing']['stage_c_analysis_seconds'] for c in generated),'stage_d_fit_seconds':sum(json.loads((out/'finalists'/str(seed)/'candidate.json').read_text())['timing']['stage_d_fit_seconds'] for seed in summary['finalist_seeds']),'retained_world_bytes':sum(v['world_bytes'] for v in audit['finalists'].values())}
    audit['cost']['all_generated_world_bytes']=sum(v['world_bytes'] for v in audit['worlds'].values())
    audit['cost']['all_saved_overworld_chunk_slots']=sum(v['saved_overworld_chunk_slots_including_halo_and_spawn'] for v in audit['worlds'].values())
    if (out/'temperate_refinement.json').exists():
        refinement=json.loads((out/'temperate_refinement.json').read_text())
        audit['cost']['temperate_refinement_seconds']=refinement['seconds']
    save(out/'validation_and_cost.json',audit);report(out,summary,audit);print(json.dumps(audit,indent=2))

if __name__=='__main__': main()
